describe('Search Suggestions', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should display recently searched terms as suggestions', () => {
        cy.get('input[name="search"]').type('Cypress');
        cy.get('input[name="search"]').blur(); // Trigger the suggestions to appear
        cy.get('.suggestions-list').should('be.visible');
        cy.get('.suggestions-list').contains('Cypress').should('exist');
    });

    it('should not display suggestions when there are no recent searches', () => {
        cy.get('input[name="search"]').type('NonExistentTerm');
        cy.get('input[name="search"]').blur(); // Trigger the suggestions to appear
        cy.get('.suggestions-list').should('not.exist');
    });
});
